export function social(u){
u('history',7,1,'史料判讀與早期臺灣','歷史研究由問題出發，檢視史料產生的時間、作者、目的與立場。考古遺物、文字、口述各有優點與限制，宜交叉比對。','同一事件的官方紀錄與民間日記可能強調不同面向；差異可成為追問線索，而非直接選一份丟掉。','早期臺灣不是沒有歷史；沒有文字的社會仍可透過考古與口傳研究。','挑一張老照片，分開寫「看得到的事實」與「需要查證的推論」。',[
['使用一份日記作史料，應先注意？',['字是否漂亮','作者、時間、目的與情境','頁數越多越真','是否符合自己想法'],1,'史料需放回產生情境，評估它能回答什麼與有何限制。'],
['研究沒有文字紀錄的史前生活，最適合使用？',['虛構電影當唯一證據','考古遺址與遺物','未來氣象預報','當代廣告'],1,'器物、遺構與生態遺留可提供史前生活的證據。']]);
u('history',7,1,'海洋交流、荷西與鄭氏','十七世紀臺灣進入更密集的海洋貿易網絡。荷蘭、西班牙、鄭氏與在地社群的互動，涉及貿易、政治與資源，不宜只背政權名稱。','荷蘭在臺灣南部、西班牙在北部建立據點；1662 年鄭成功取代荷蘭在臺勢力。','政權轉變不代表所有居民生活瞬間完全改變；要比較制度與延續。','畫時間線連結海上貿易、外來政權與在地社會，至少標出兩個互動。',[
['十七世紀歐洲勢力來臺的重要背景是？',['全球海洋貿易擴張','工業革命已遍及臺灣','網際網路普及','冷戰結束'],0,'大航海時代的貿易與殖民競爭促進歐洲勢力來臺。'],
['鄭成功取代荷蘭在臺勢力的時間為？',['1624 年','1662 年','1895 年','1945 年'],1,'1662 年是鄭成功取得荷蘭在臺據點的重要時點。']]);
u('history',7,2,'清領與日治時期的變遷','研究清領到日治，要比較行政、經濟、教育與基礎建設，也看見不同群體承受的影響。現代化建設與殖民控制可能同時存在。','1895 年《馬關條約》後進入日治時期。鐵路、衛生、學校制度的改變需與治理目的及差別待遇一起分析。','有建設不等於沒有壓迫；只用好或壞兩個詞難以解釋複雜史實。','選交通或教育為主題，整理制度改變、受益者與承受成本者。',[
['臺灣進入日治時期的重要條約是？',['南京條約','馬關條約','凡爾賽條約','里斯本條約'],1,'1895 年《馬關條約》是清廷割讓臺灣等地的條約。'],
['分析殖民時期鐵路建設，最完整的觀點是？',['只看有無鐵軌','同時考慮運輸改善、經濟利益及治理目的','只背火車顏色','只看單一人的感受'],1,'基礎建設具有多重功能，需要考量政策目的及不同群體的經驗。']]);
u('history',7,2,'戰後臺灣與民主化','戰後臺灣歷經政治、人口、產業與社會變遷。民主化是制度調整與社會參與的長期過程，包含人權保障、政黨競爭與公共討論。','1987 年解除戒嚴是重要節點；理解民主發展還需連結此前與此後的社會運動、制度改革。','民主化不是某一天突然全部完成；經濟成長也不代表所有群體同樣受益。','以時間線整理戰後臺灣的政治與經濟事件，避免把同時發生誤認為因果。',[
['臺灣解除戒嚴的重要年份是？',['1945','1949','1987','2008'],2,'1987 年解除戒嚴是臺灣民主化歷程的重要節點。'],
['要研究民主化歷程，哪種方式較完整？',['只背一位人物','比較制度變遷與社會參與','只看人口總數','完全不讀史料'],1,'制度、社會運動與不同參與者共同構成歷程。']]);
u('history',8,1,'中國與東亞：制度及文化交流','閱讀東亞史需要時間與空間框架，追蹤政治制度、人口移動、宗教與技術的傳播。交流是雙向選擇與再詮釋，不只是單向複製。','隋唐時期的制度與文化影響東亞，佛教經交通網絡傳播到不同地區並發展在地特色。','朝代順序只是工具，還要能解釋制度為何變、對誰有影響。','比較科舉與世襲在人才選取方式上的差異，說明各自限制。',[
['科舉與單純世襲相比，主要差別是？',['透過考試選取部分人才','完全沒有階層差異','人人一定當官','不需要教育'],0,'科舉以考試作選才機制，但受教育資源等因素限制。'],
['文化傳入另一地區後，常見情況是？',['永遠完全不變','必定全被拒絕','與當地條件互動產生調整','當地文化立即消失'],2,'文化交流包含接受、改造與在地化。']]);
u('history',8,2,'近代東亞與帝國主義','十九世紀東亞面對工業化國家的軍事與貿易壓力，出現不同改革與抵抗。比較事件需辨別外部條件、內部制度和不同社群的選擇。','日本明治維新推動制度與產業改革；中國晚清也出現洋務、戊戌變法等改革嘗試，其目標和深度不盡相同。','不能把不同時期改革混成同一事件，也不能用結果倒推當時只有一條路。','用表格比較兩項改革的背景、目標、措施與限制。',[
['明治維新主要發生在哪個國家？',['日本','印度','法國','巴西'],0,'日本在十九世紀後半推動明治維新。'],
['比較晚清改革時，哪組分類最有幫助？',['人物身高、服裝顏色','背景、目標、措施、影響','只比名稱長短','只看現代印象'],1,'一致的比較向度能呈現改革異同與因果關係。']]);
u('history',9,1,'古代文明到近代歐洲','世界史可從文明發展、宗教、城市與政治制度觀察長期變遷。文藝復興、宗教改革、科學革命與啟蒙思潮有不同關懷，也互相影響。','啟蒙思想重視理性思辨、權利與政治正當性；不能把所有近代思想都等同單一主張。','避免將現代國家界線直接套進古代世界。','為文藝復興、宗教改革、啟蒙思想各寫一個關鍵問題，而不只背名稱。',[
['啟蒙思想常強調？',['禁止一切理性討論','理性與對權力正當性的思考','所有人必須同一職業','回到完全沒有文字'],1,'啟蒙思想者透過理性探討政治、社會與權利等問題。'],
['讀古代文明地圖時，應避免？',['核對河流','注意年代','把今天國界視為古代固定國界','比較交通路線'],2,'國家與疆界隨時間變化，需回到當時時空。']]);
u('history',9,2,'工業革命、世界大戰與全球化','工業革命改變生產、都市和勞動關係。兩次世界大戰及冷戰需結合國際秩序、民族主義與多重因素理解。全球化增加連結，也帶來不均。','機械化工廠提高產量，也產生勞動條件和都市環境問題；全球貿易使產品分工跨越多國。','歷史事件通常有多重原因，導火線不等於全部根本原因。','選一項日用品，追蹤跨國生產鏈並比較誰獲益、誰承受風險。',[
['工業革命的重要生產變化是？',['大量轉向機械與工廠生產','完全取消城市','只剩家庭農作','國際貿易消失'],0,'機械化與工廠制度是工業革命的重要變化。'],
['區分戰爭導火線和背景因素的目的為何？',['讓原因只剩一個','避免把直接觸發事件當成全部原因','不再閱讀資料','保證任何戰爭都無法避免'],1,'需要分開長期結構、情勢與直接觸發事件。']]);

u('geography',7,1,'地圖、比例尺與經緯度','地圖先讀圖名、方向、圖例和比例尺。經度表示相對本初子午線的東西位置，緯度表示相對赤道的南北位置。','比例尺 1:50,000，圖上 2 cm 代表實地 100,000 cm＝1 km。','比例尺分母越小，比例尺越大；相同紙面通常可呈現更細的局部。','畫上學路線，加入方向與圖例，說明示意圖和等比例地圖的不同。',[
['1:100,000 地圖上 3 cm，實地為？',['300 m','3 km','30 km','300 km'],1,'3×100000＝300000 cm＝3 km。'],
['赤道的緯度為？',['0°','23.5°N','90°N','180°'],0,'赤道是緯度 0° 的基準線。']]);
u('geography',7,1,'臺灣地形、氣候與災害','臺灣地形與板塊活動、流水作用等相關；降雨受季風、颱風、地形與季節影響。災害風險也取決於暴露人口與環境脆弱程度。','同樣降雨量，陡坡開發、排水條件與土地利用不同，可能產生不同災害結果。','不能只靠「雨大」解釋全部淹水，也要檢查地勢、排水與使用方式。','用校園地圖標記易積水處，提出一個可以觀測驗證的原因。',[
['等高線越密集，一般表示？',['坡度較陡','坡度較緩','海拔一定為零','必有城市'],0,'相同高度差在更短水平距離內發生，表示坡度陡。'],
['災害風險除了自然現象，還需考慮？',['人口暴露與脆弱程度','只有地名','只有行政區大小','所有地方必一樣'],0,'相同自然事件在不同人口、設施與準備條件下，影響不同。']]);
u('geography',7,2,'臺灣人口、產業與都市','人口變化受出生、死亡與遷移影響。產業分工與交通、技術、資本和市場相關；都市化改變生活機會與空間使用。','某地自然增加為負，但若移入多於移出，總人口仍可能增加。','人口密度是人口÷面積，不等於人口總數；服務業不一定是低技術。','比較兩地人口密度與總人口，說明為何排名可能不同。',[
['人口 60,000 人、面積 20 km²，密度為？',['300 人/km²','3000 人/km²','1200 人/km²','1200000 人/km²'],1,'60000÷20＝3000 人/km²。'],
['出生少於死亡，總人口仍增加，可能因？',['大量淨移入','所有人變年輕','面積變大','統計一定錯'],0,'總人口變化＝自然增加＋社會增加，淨移入可抵銷自然減少。']]);
u('geography',8,1,'東亞與區域差異','區域比較應同時看自然環境、人口、產業與歷史文化。季風區、內陸乾燥區與高地的生活方式不同，也隨技術與社會變化調整。','沿海地區的港口和市場可能有利貿易，但產業發展還受到政策、人才與交通影響。','區域不是每一處都一樣，也不宜以單一氣候決定所有人的生活。','以海陸位置、降雨、交通三項比較沿海與內陸地區。',[
['比較東亞沿海與內陸降雨，重要因素是？',['距海與水氣輸送','文字字體','每人姓名','國旗顏色'],0,'海陸位置與風向影響水氣可達程度。'],
['說明一個港口城市發展，較適當的是？',['只靠緯度','綜合交通、市場、政策與歷史','只有雨量','所有港口必同樣繁榮'],1,'城市發展是多種自然與人文條件的共同結果。']]);
u('geography',8,2,'亞洲、非洲與文化地景','不同區域的氣候、水資源、歷史與宗教形塑文化地景。研究一地需要尊重內部差異，避免把大洲居民視為單一文化。','乾燥區水資源影響聚落與農業分布；灌溉和貿易能改變限制，但也有環境成本。','宗教與國家不能一一畫等號；同一區域內存在多樣生活方式。','比較兩個區域的水資源使用，提出自然與人為因素各一項。',[
['乾燥區聚落常靠近綠洲或河流，主要原因？',['水資源較易取得','一定沒有交通','人口不得遷移','只有緯度決定'],0,'水是生活與農業的重要條件，影響聚落分布。'],
['介紹非洲文化最應避免？',['查資料來源','說明區域差異','以單一刻板印象代表整個大洲','尊重不同語言'],2,'大洲內自然與文化多樣，不能以單一印象概括。']]);
u('geography',9,1,'歐洲、美洲與大洋洲','區域地理以位置、自然環境、人群遷移、產業與國際連結交互分析。比較農業或工業應注意尺度及區域內差異。','大規模農場是否可行，與土地、機械、資本、市場和制度都有關，不是單靠地廣人稀。','洲與國家不同，不能把美洲等同於美國。','為兩個國家建立四欄比較表：環境、人口、產業、對外連結。',[
['研究商業性大規模農業，需考量？',['只有國旗','土地、資本、機械與市場','只看語言','任何地方完全一樣'],1,'商業農業需要投入、土地條件與銷售市場配合。'],
['下列哪項是正確的地理尺度觀念？',['美洲等於美國','歐洲等於單一國家','國家內部仍有區域差異','大洋洲沒有島嶼'],2,'同一國家內也有自然與人文差異。']]);
u('geography',9,2,'全球連結與環境議題','全球生產與消費使地方相互依賴。永續議題需比較環境、社會與經濟影響，並辨識不同利害關係人的需求。','水庫供水有益生活與產業，也可能改變河川生態與社區；方案需比較替代選項及成本。','永續不是只看單一指標，也不是任何開發都必定好或壞。','分析校園瓶裝水使用，提出減量方案與檢核指標。',[
['評估開發方案時，最完整的方法？',['只看收益','只看一張照片','比較環境、社會、經濟與替代方案','不聽當地居民'],2,'多面向比較可辨識取捨與受影響群體。'],
['商品零件來自多國，最能說明？',['全球分工與連結','所有國家完全獨立','交通沒有作用','不存在貿易'],0,'生產鏈跨越不同地區，反映國際分工。']]);

u('civics',7,1,'自我、群體與多元文化','個人同時具有多種身分，透過家庭、同儕、學校與媒體學習社會規範。尊重差異須辨識刻板印象、偏見與歧視，不以群體標籤取代個人理解。','「某性別不適合當班長」以群體印象限制個人機會；評估應回到能力與公平程序。','尊重文化差異不代表放棄對人權傷害的討論。','記錄一則廣告的角色分配，指出可能的刻板印象並重新設計。',[
['「女生都不擅長科學」屬於？',['逐一查證的個人評估','性別刻板印象','自然定律','公平選拔'],1,'以性別概括所有人的能力，忽略個別差異。'],
['面對與自己不同的文化，較合宜的是？',['先理解脈絡並尊重差異','立即判定低等','拒絕接觸','把每個人當完全相同'],0,'理解與尊重有助對話，也保留對具體問題的理性討論。']]);
u('civics',7,2,'家庭、學校與公共參與','家庭與學校提供照顧、學習與互動場域。公共事務需要傾聽、提出理由、協商和檢討，參與不是只有投票當天。','班級討論作業安排，可先蒐集需求、列方案、比較影響，再決定與回顧。','多數決不代表可以侵害少數者基本權利。','選一項班級問題，寫出利害關係人、方案、理由與評估方法。',[
['班會多數同意排擠一位同學，這決定是否正當？',['多數同意就永遠正當','不正當，仍需尊重基本權利','看班長喜好','只要不寫下就可以'],1,'多數決受人權保障與程序正義限制。'],
['公共討論遇到不同意見，應？',['先確認對方理由再回應','禁止對方說話','只比音量','散布對方隱私'],0,'釐清理由與需求，才能協商可行方案。']]);
u('civics',8,1,'民主政治與權力分立','民主需要公共參與、權力制衡與權利保障。政府權力須有制度限制，資訊公開與問責使人民能檢視政策。','討論政策時，應分清提出、執行與監督的角色，並核對法定權限。','有選舉不表示其他民主條件自動具備；不能用選票取消所有權利保障。','為校園自治設計提案、討論、執行與監督流程。',[
['權力分立與制衡主要目的？',['使任何人都不用負責','避免權力過度集中','讓所有決策無法進行','取消人民參與'],1,'分工與互相監督可降低濫權風險。'],
['檢視公共政策時，哪項最符合問責精神？',['不准提問','要求說明決策依據與執行結果','只看口號','隱藏所有資料'],1,'問責要求權力行使者說明並接受檢視。']]);
u('civics',8,2,'人權、法治與正當程序','法治強調權力依法且受限制，保障人格尊嚴、權利與救濟。爭議處理應重視證據、陳述機會與公正程序。本站用概念情境學習，不替代個案法律判斷。','處理校園違規前先查證事實、讓當事人說明、依規範作成合比例處置，比先定罪再找理由更符合程序精神。','有規則不代表一定正當；規則內容與執行方式都要接受檢驗。','替班規設計申訴與覆查程序，避免由同一人決定所有事情。',[
['處理爭議時，何者最符合正當程序？',['未調查先處罰','讓當事人陳述並檢視證據','只聽最受歡迎的人','不告知理由'],1,'陳述、證據與理由是公平程序的重要條件。'],
['保障人權的對象應是？',['只限成績好的人','只限多數族群','每個人','只限有投票權的人'],2,'人權基於人的尊嚴，不因成績或身分而被排除。']]);
u('civics',9,1,'選擇、機會成本與市場','資源有限使人需要選擇。機會成本是放棄的最佳替代方案價值，不是所有放棄項目的總和。供需分析需先固定其他條件。','只有一小時，選讀書就可能放棄最想做的運動；不是把所有可能休閒價值加總。','需求量與需求變動不同；價格改變通常是沿既有需求關係變動。','規劃 200 元活動預算，列出最佳替代方案與選擇理由。',[
['機會成本指？',['所有選项總價','放棄的最佳替代方案價值','已付錢一定全算','完全沒有代價'],1,'選擇使最佳可行替代方案被放棄，其價值構成機會成本。'],
['其他條件不變，某商品價格上升，通常需求量會？',['增加','減少','無限大','必為零'],1,'一般需求法則：其他條件相同時，價格與需求量反向變動。']]);
u('civics',9,2,'媒體素養、全球化與永續消費','媒體訊息需核對來源、時間、證據與傳播目的。全球消費連結勞動與環境，公民可透過資訊查證、參與討論和行動回應。','看到「震驚！所有人都必須轉傳」先找原始公告與可靠資料，不以分享數判定真假。','截圖可能缺乏上下文；搜尋到多篇相同文章，也可能都抄同一錯誤來源。','選一則網路消息，記錄原始來源、查證路徑及仍不確定處。',[
['判斷消息可信度，最好先做？',['看轉傳次數','找原始來源與可查證證據','只看驚嘆號','朋友傳就相信'],1,'原始來源與證據比人氣更能支持可信度。'],
['多家網站文章一模一樣，是否等於多個獨立證據？',['一定是','不一定，可能複製同一來源','一定全假','與查證無關'],1,'應追查來源鏈，確認是否真有獨立資料。']]);

u('history',7,1,'臺灣南島語族與多元原住民族文化','臺灣是南島語族擴散的重要發源地之一。史前時期歷經舊石器時代（長濱文化，採集漁獵）、新石器時代（圓山文化，磨製石器、農業陶器）到金屬器時代（十三行文化，煉鐵、煉玻璃、具貿易網絡）。原住民族依社會體系有母系社會（阿美族、卑南族）、貴族領袖制（排灣族、魯凱族）及父系社會（泰雅族、布農族）等多元文化。','新北市八里十三行遺址出土的大量鐵渣、玻璃珠、瑪瑙與中國唐宋銅錢，證實千年前十三行人已具備煉鐵技術並與海外人群展開頻繁貿易。','南島語族原住民各族擁有不同語言、宗教祭儀與社會制度，不可視為單一均質群體；平埔族群依然具有鮮明文化傳承與在地認同，並非自然消失。','整理臺灣原住民族主要祭典（如阿美族豐年祭、賽夏族巴斯達隘矮靈祭、達悟族飛魚祭）的文化內涵與生態倫理。',[
 ['新北市八里區的「十三行文化」出土了煉鐵爐殘渣、外來玻璃珠與銅錢，這代表該文化已邁入臺灣史前哪一個時代？',['舊石器時代晚期','新石器時代早期','金屬器時代','日治現代工業時期'],2,'十三行文化以出土煉鐵遺跡、玻璃器物及海外貿易品為特徵，屬於臺灣史前的金屬器時代。'],
 ['在臺灣原住民族的傳統社會組織中，以母系社會與氏族繼承為主要特徵的族群包括？',['泰雅族與賽德克族','阿美族與卑南族','布農族與鄒族','達悟族與邵族'],1,'阿美族與卑南族傳統上屬於母系社會，財產繼承與家族事務多由女性主導，男性則負責公共防衛與年齡階級組織。']]);
u('history',8,1,'中國古代國家形成與封建帝制','商代甲骨文與青銅器反映神權統治；西周建立宗法制度（嫡長子繼承制）、封建制度（封邦建國、層層分封）與井田禮樂，形成等級社會秩序。春秋戰國鐵器牛耕普及，封建瓦解，諸子百家爭鳴；秦始皇廢封建立郡縣、統一度量衡車軌文字，確立大一統中央集權官僚體制。','西周宗法制規範「大宗」百世不遷、「小宗」五世則遷，將血緣宗族與國家政治權力緊密結合；秦代郡縣長官由朝廷直接任免、不得世襲，徹底打破貴族世襲特權。','西周的「封建」是血緣家族親疏的政治分封，與歐洲中古封建領主農奴制內涵不同；諸子百家（儒、道、法、墨）是因應戰國社會大變動所提出的救世方案，非純空想學說。','繪製圖表比較西周「封建制度」與秦朝「郡縣制度」在地方長官任用方式、統治核心與中央控制力上的根本差異。',[
 ['西周建立統治秩序時，將政治分封與宗族血緣組織緊密結合的核心制度是？',['科舉制度','九品官人法','宗法制度','行省制度'],2,'西周以宗法制度（特別是嫡長子繼承制）為核心，維繫天子、諸侯、卿大夫間的政治權力與家族親疏關係。'],
 ['秦始皇統一天下後，在地方治理上全面廢除封建制度，推行的新體制是？',['郡縣制','分封諸侯制','世卿世祿制','封建盟約制'],0,'秦朝廢除分封世襲的諸侯，推行由皇帝直接任免地方長官（郡守、縣令）且不得世襲的「郡縣制」，加強中央集權。']]);
u('history',8,2,'明清社會變遷與西力東漸','明清時期江南市鎮經濟高度繁榮，美洲白銀大量流入促成「一條鞭法」與「攤丁入畝」賦稅改革（實物徭役改為折銀繳納）。明末清初利瑪竇等天主教耶穌會傳教士來華，引進西方天文、曆法、幾何與世界地圖（萬國輿圖），開啟早期中西文化交流，後因禮儀之爭演變為禁教。','徐光啟與利瑪竇合作翻譯《幾何原本》，李時珍撰成《本草綱目》，宋應星著《天工開物》，展現明清時期實用科技與傳統格物學問的融合進展。','明清市鎮雖然商貿繁華，但官方長期實施海禁或朝貢貿易政策，阻礙了自發性海外擴張；傳教士帶來的科學知識主要停留在朝廷欽天監，並未全面普及於民間社會。','整理利瑪竇與徐光啟交流的歷史背景，說明傳教士如何利用西洋科學（如曆法、火器、輿圖）作為在中國傳播天主教的媒介。',[
 ['明代後期美洲白銀因海外貿易大量流入中國，促使政府在賦稅制度上推行何項重大改革？',['兩稅法改收米粟','一條鞭法改以白銀折算繳納','均田制分配田地','初稅畝按畝徵收'],1,'明代張居正推行「一條鞭法」，將田賦、徭役與雜稅合併，簡化為按田畝計稅並一律改以白銀折納。'],
 ['明末天主教耶穌會傳教士利瑪竇來到中國傳教，為了爭取朝廷與士大夫信任，主要採取何種傳教策略？',['以強大武力強迫所有人受洗','融入儒家文化並介紹西方天文數學與地圖科技','禁止所有人讀書識字','要求信徒完全捨棄原有中文姓名'],1,'利瑪竇穿儒服、讀儒書，並帶來西洋天文鐘、三稜鏡、《幾何原本》與《坤輿萬國全圖》，開創「學術傳教」路線。']]);
u('history',9,1,'古希臘羅馬古典文明與民主法律','古希臘由愛琴海多島多山環境演育出城邦政治。雅典發展出公民大會、陶片放逐法之直接民主（限成年男性公民）；斯巴達採寡頭軍事體制。希臘哲學（蘇格拉底、柏拉圖、亞里斯多德）奠定西方理性思辨根基。羅馬歷經王政、共和到帝國，建立護民官與元老院制度，制定《十二表法》與羅馬法體系，影響現代西方法治與私法原則。','雅典公民透過抽籤與舉手表決直接參與城邦公共決策；羅馬《十二表法》將習慣法銘刻於銅表公開於廣場，保障平民免受貴族任意專斷判決。','雅典直接民主制度中婦女、奴隸與外邦人皆無公民投票權；羅馬帝國由屋大維（奧古斯都）開啟元首制，元老院權力實質被架空，已非共和體制。','比較古希臘雅典的「公民直接民主」與現代國家的「代議民主制度」在參與人口範圍、決策程序與治理效率上的異同。',[
 ['西方歷史上首創公民大會、由成年男性公民直接參與投票表決城邦重大事務的古希臘城邦是？',['斯巴達','雅典','馬其頓','特洛伊'],1,'雅典是西方民主政治的發源地，其成年男性公民可直接在公民大會上討論與表決法律政策。'],
 ['羅馬共和國時期公布的第一部成文法典，將法律公開銘刻於青銅板上以限制貴族任意解釋法律的是？',['《漢摩拉比法典》','《十二表法》','《查士丁尼法典》','《拿破崙法典》'],1,'西元前五世紀公布的《十二表法》是羅馬第一部成文法典，打破貴族壟斷法律解釋，奠定羅馬成文法治基礎。']]);

u('geography',7,1,'等高線地形圖判讀與臺灣水文環境','等高線閉合處數值外低內高為山頂、外高內低為盆地；等高線向數值低處凸出為山脊（分水嶺），向數值高處凸出為山谷（常有溪流河流）。臺灣中央山脈縱貫中央形成東西分水嶺，地勢高峻、河短流急，夏秋颱風暴雨洪峰集中，乾季水量驟減，水資源涵養儲存不易。','濁水溪為臺灣最長河川，高屏溪流域面積最大。由於地質脆弱且坡度陡峭，豪雨時常造成嚴重水土流失並使水庫淤積，因此需興建水庫、沉沙池與越域引水設施。','等高線向高處凸出的是「山谷」而非山脊（水往低處流，故河流必在山谷中）；臺灣年平均降雨量達 2500 毫米（約全球平均 3 倍），但因河短坡陡、降雨時空不均，仍屬相對缺水地區。','在一張等高線地形圖上找出最高峰、一處鞍部、一處山脊與一條潛在河流路徑，並說明判斷理由。',[
 ['在地形圖的等高線判讀中，若等高線彎曲呈現 V 字形，且尖端指向「海拔數值較高處」，該地形特徵為？',['山脊（分水嶺）','山谷（可能發育溪流）','陡崖峭壁','開闊高原'],1,'等高線凸向高處為山谷（地勢低窪之處），降水匯集易形成河流；凸向低處則為山脊。'],
 ['臺灣年平均降雨量高達 2500 毫米以上，但人均可用水量卻偏低，名列全球缺水地區之一，其主要自然原因為？',['臺灣島降雨完全蒸發，無地表逕流','地勢高聳坡度陡急、河短流急且降雨季節時空分布不均','地下水層完全被海水倒灌無可用淡水','氣溫過低降雪無法熔化'],1,'臺灣因山勢陡峭、河川短促湍急，大部分雨水迅速流入海洋；加上冬夏降雨時空分布不均，儲水極為不易。']]);
u('geography',8,1,'季風亞洲與世界文明搖籃','東亞、南亞與東南亞受海陸比熱差異影響形成顯著的季風氣候（夏季吹向大陸帶來豐沛暖濕水氣，冬季吹向海洋寒冷乾燥）。季風亞洲雨熱同期的氣候特點極度有利於水稻種植，造就精耕細作的集約農業與世界最高人口密度聚居區。印度河、恆河、黃河與長江流域孕育了深厚悠久的人類古典文明。','南亞印度半島夏季吹西南季風帶來豐沛雨水，若西南季風遲來或雨量不足，常引發旱災與農作歉收；恆河平原土壤肥沃、水源充足，是世界人口最稠密農業區之一。','季風氣候雖降水豐沛，但季風具有年際不穩定性（強弱早晚不一），容易造成水旱災交替；東南亞赤道附近（如印尼、馬來群島）主要屬熱帶雨林氣候，終年高溫多雨，非典型季風氣候。','繪製簡單示意圖，說明冬季與夏季亞洲大陸與太平洋/印度洋之間的高低氣壓分佈與季風風向轉變機制。',[
 ['季風亞洲廣大地區之所以能發展高產量的「水稻農業」並撫養世界最龐大人口，其最主要的氣候優勢為？',['終年寒冷乾燥使病蟲害完全消失','夏季高溫多雨、雨熱同期','全年溫和少雨利於機械耕作','冬季強烈東北季風帶來高溫'],1,'夏季季風帶來太平洋與印度洋暖濕水氣，高溫且多雨（雨熱同期），最契合水稻喜熱喜濕的生長生理需求。'],
 ['南亞印度半島在夏季盛行的季風風向主要為？',['西北季風','西南季風','東北季風','東南季風'],1,'夏季南亞大陸強烈受熱形成低氣壓，南半球東南信風越過赤道受科氏力向右偏轉，形成溫暖潮濕的「西南季風」。']]);
u('geography',9,1,'美國與北美洲區域發展特色','北美洲地形呈三大縱列帶：東部古老低矮阿帕拉契山脈、中部廣大平原（密西西比河流域）、西部高峻年輕落磯山脈。美國利用廣袤平原與氣候多樣性發展高度專業化、大規模機械化農業帶（如玉米帶、小麥帶、棉花帶）。五大湖與東北部為傳統鋼鐵汽車重工業區；近年朝向南部與西部「陽光帶」的高科技矽谷、航太與服務業轉移。','美國中西部玉米帶地勢平坦、土壤肥沃，利用 GPS、無人機與大型聯合收割機進行精準農業，農場規模龐大但勞動力需求極少，農產品高度商業化並外銷全球。','大規模專業化商業農業雖然生產效率極高，但單一作物種植容易造成土壤地力消耗、過度依賴化肥農藥與地下水超抽，具生態永續風險。','整理美國農業區域圖，標示出「玉米帶」、「小麥帶」與「酪農帶」的地理分佈位置，並說明其與氣候雨量溫度的對應關係。',[
 ['美國北美大平原地區的農業經營模式具有何種顯著特徵？',['小農小塊土地耕作、高度依賴人工密集','大規模土地經營、高度機械化與高度市場專業化','完全不使用任何現代機械設備','只種植自給自足糧食，絕不對外販售'],1,'美國農業以「地廣人稀、資本雄厚」為背景，發展出農場規模大、機械化程度高、區域專業化生產與商業導向為特色。'],
 ['北美洲的地形結構大致呈現東、中、西三大縱列，其中位於西部、地勢最高峻且屬於環太平洋地震帶的山脈是？',['阿帕拉契山脈','落磯山脈','烏拉山脈','阿爾卑斯山脈'],1,'北美洲西部為年輕褶皺造山形成的「落磯山脈」，地勢高聳險峻，並伴隨板塊造山活動與地熱資源。']]);

u('civics',7,1,'少年法律保護與權益維護','法律考量少年（12 歲以上未滿 18 歲）身心發展尚未成熟，以保護優先而非純懲罰。《少年事件處理法》分為少年保護事件（少年偏差行為或觸法情節輕微，施以訓誡、假日生活輔導、保護管束、感化教育）與少年刑事案件（觸犯重罪者始適用刑法）。《兒童及少年福利與權益保障法》保障兒少免於受虐、剝削與身心侵害。','少年無照駕駛或涉入聚眾滋事，少年法院法官審酌其家庭環境與再犯風險，可裁定責付家長管教或交付少年保護官執行「保護管束」，輔導其健全成長。','未成年人觸法並非完全「免罰」或「不會有事」，少年保護處分依然具有法定拘束力與管束限制；任何人不得公開報導或揭露少年事件當事人姓名與身分資訊。','繪製流程圖，說明一名 14 歲國中生若有觸法或偏差行為時，少年保護體系（保護處分）與一般成年人刑事懲罰程序有何核心差異。',[
 ['依據我國《少年事件處理法》之立法意旨，處理未滿 18 歲少年觸法事件時，其最優先的核心原則是？',['一律判處極刑加重處罰','健全少年自我成長，以保護與輔導為優先','公開身分資訊供大眾警惕','直接剝奪所有就學權利'],1,'少年事件處理法首重「保護健全成長」之教育主義，透過適當環境調整與保護處分矯治少年偏差，非以應報刑罰為主。'],
 ['少年法院法官在審理少年保護事件後，認為少年需要專業輔導定期至法院報到會談，可裁定何種處分？',['死刑','保護管束','罰金','無期徒刑'],1,'保護管束為少年保護處分之一，由少年保護官定期約談指導，協助少年改善家庭與生活常規。']]);
u('civics',8,2,'現代法治體系：民法、刑法與行政法','現代法治國家依法律性質劃分：民法處理私人間財產與身分關係（私法自治、契約自由、侵權行為損害賠償）；刑法處理犯罪與刑罰（罪刑法定原則，明定何種行為是犯罪及處罰標準）；行政法規範政府行政權行使與人民公法權益救濟（行政處分、訴願與行政訴訟）。','跟同學借筆記本不小心弄壞需負民事損害賠償責任；無故竊取他人手機涉犯刑法竊盜罪需負刑事責任；未戴安全帽被交通警察開罰單屬於行政罰，不服可循行政救濟。','民事賠償是由被害人向法院提起民事訴訟，非檢察官公訴；刑事責任講求「罪刑法定」，法律無明文規定處罰者不得定罪。民事、刑事與行政責任可能因同一個違法行為同時發生（如酒駕肇事）。','列舉一個生活案例（如車禍撞傷行人），分別分析肇事者可能面臨的民事責任、刑事責任與行政責任。',[
 ['刑法中最核心的基本原則，明定「行為之處罰，以行為時之法律有明文規定者為限」的是？',['契約自由原則','誠實信用原則','罪刑法定原則','無過失責任原則'],2,'「罪刑法定原則」是現代刑法的基石，防止國家權力濫用，保障人民自由免受溯及既往或恣意定罪之侵害。'],
 ['民眾若因超速闖紅燈收到警察局開立的交通違規罰單，該張罰單在法律性質上屬於？',['民事契約','刑事判決','行政處分','立法院法律案'],2,'行政機關就公法上具體事件所為對外直接發生法律效果之單方行政行為，稱為「行政處分」。']]);
u('civics',9,1,'市場競爭、外部效果與政府管制','市場價格由買賣雙方的供給與需求共同決定。外部效果是指經濟活動對未參與交易的第三人產生影響且未在價格中反映：外部成本（負外部性，如工廠排放廢氣）造成社會成本大於私人成本，導致生產過量，政府可藉課稅或開罰管制；外部效益（正外部性，如施打疫苗、受教育）造成社會效益大於私人效益，政府可提供補貼獎勵。','火力發電廠發電提供用電便利，但排放空氣汙染危害周遭居民健康，屬於外部成本；政府向排碳業者徵收碳費（排碳稅），將外部成本內部化。','外部成本與外部效益並非指商品本身的優缺點，而是指對「交易雙方以外的第三人」產生的未計價影響；市場機能無法自動解決外部效果時，即發生「市場失靈」。','分析「搭乘大眾運輸工具」具有哪些外部效益，並討論政府推出通勤月票補助在經濟學上的政策理由。',[
 ['工廠製造商品過程中排放未經處理的廢水汙染河川，導致下游農民農作受損且未獲得任何賠償，此現象在經濟學上稱為？',['外部效益（正外部性）','外部成本（負外部性）','完全競爭市場平衡','公共財自由搭便車'],1,'經濟主體的行為對交易以外的第三人造成損害卻無需支付代價，屬於「外部成本」，會造成社會資源配置失當。'],
 ['政府為了鼓勵民眾施打流感疫苗以建立群體免疫防護網（具有外部效益），最常採取的經濟政策工具是？',['對施打疫苗者課徵重稅','提供公費補助或免費施打獎勵','完全禁止民間自行施打','關閉所有基層診所'],1,'對於具有正外部性（外部效益）的活動，市場自行生產量往往低於社會最適水準，政府透過發放津貼或補助鼓勵消費。']]);
u('history',7,2,'清領開港通商與臺灣近代化建設','1858 年英法聯軍《天津條約》與 1860 年《北京條約》後，臺灣陸續開放安平、淡水、雞籠（基隆）、打狗（高雄）四港。洋行設立，外商輸入鴉片、紡織品，出口茶、糖、樟腦「三寶」，貿易轉為出超；經濟重心北移，茶葉帶動大稻埕繁榮。牡丹社事件後，沈葆楨來臺開山撫番、建億載金城；中法戰爭後 1885 年臺灣建省，首任巡撫劉銘傳推動修築鐵路（基隆至新竹）、架設電報、設郵政總局與西學堂。','樟腦與茶葉多產於北部丘陵與山區，帶動新北、桃竹苗客家族群與丘陵拓墾，淡水河口的大稻埕洋行林立，取代南部府城（台南）成為全臺最大商業集散中心。','開港通商是受西方列強條約逼迫開放，非清廷主動開明；劉銘傳推動現代化改革面臨財政困難、守舊反對與原住民衝突，鐵路在他離臺時僅完成基隆到臺北。','繪製簡圖標示清末臺灣開放的四處主要港口與「茶、糖、樟腦」三大出口特產的主要產區分佈。',[
 ['清末臺灣因英法聯軍戰後簽訂條約開港通商，帶動臺灣對外貿易大幅轉為出超的三大主力出口商品是？',['稻米、甘蔗、鹿皮','茶葉、蔗糖、樟腦','黃金、煤炭、鐵礦','鴉片、布匹、香料'],1,'清末開港後，茶葉、蔗糖與樟腦成為臺灣最重要的大宗外銷物資，被稱為「臺灣三寶」，使臺灣對外貿易轉為出超。'],
 ['臺灣於 1885 年正式設省，積極推動興建全臺第一條客運鐵路、架設電報線與開辦新式郵政的巡撫是？',['施琅','沈葆楨','劉銘傳','丁日昌'],2,'劉銘傳為臺灣建省後首任巡撫，大刀闊斧推動各項近代化建設，包括鋪設基隆至新竹鐵路、架設電報與創立西學堂。']]);
u('history',8,2,'辛亥革命與中華民國建立到對日抗戰','孫中山創立興中會、同盟會，提出三民主義（民族、民權、民生）。1911 年 10 月 10 日武昌起義爆發，各省響應獨立；1912 年 1 月 1 日中華民國於南京宣告成立，結束兩千多年君主專制。民國初年歷經袁世凱稱帝與軍閥割據；新文化運動高舉「德先生（民主）與賽先生（科學）」，白話文運動普及。1937 年七七盧溝橋事變揭開八年抗戰序幕，1943 年《開羅宣言》聲明日本戰後歸還東北與臺灣、澎湖。','胡適發表〈文學改良芻議〉提倡白話文、陳獨秀創辦《新青年》，推動思想啟蒙與反封建禮教；對日抗戰期間國民政府遷都重慶，歷經淞滬會戰、武漢會戰等持久抗戰消耗日軍。','武昌起義成功時孫中山人在海外，革命是各省革命黨人、新軍與立憲派力量匯聚的成果；新文化運動注重思想與文化批判，五四運動則是 1919 年因巴黎和會山東問題爆發的學生愛國群眾運動。','列出新文化運動中提出的「德先生」與「賽先生」各自代表的現代核心價值，並說明白話文對平民教育普及的重大意義。',[
 ['辛亥革命推翻清朝君主專制統治，建立亞洲第一個民主共和國，該革命爆發的標誌性事件是？',['廣州黃花崗起義','武昌起義','金田起義','義和團運動'],1,'1911 年 10 月 10 日武昌新軍起義爆發並佔領武漢三鎮，引發各省紛紛宣告獨立，促成清帝退位與中華民國創立。'],
 ['民國初年陳獨秀、胡適等知識分子推動「新文化運動」，極力提倡的「德先生」與「賽先生」分別指？',['道德與正義','民主與科學','德國與塞爾維亞','自由與平等'],1,'德先生（Democracy，民主）與賽先生（Science，科學）是新文化運動的兩大思想旗幟，主張破除迷信、啟迪民智。']]);
u('history',9,2,'二次大戰後冷戰對峙與全球解殖潮','二戰後以美國為首的資本主義民主陣營（成立北約組織 NATO）與以蘇聯為首的共產極權陣營（華沙公約組織）形成「冷戰」長期對峙。美蘇避免全面核戰，透過代理人戰爭（如韓戰、越戰）、軍備競賽與太空競賽爭霸；歐洲分裂（柏林圍牆）。亞洲與非洲在戰後掀起大規模「去殖民化」民族獨立浪潮，印度（甘地非暴力不合作運動後獨立）、東南亞與非洲諸國相繼脫離歐美殖民統治。1991 年蘇聯解體標誌冷戰結束。','韓戰（1950-1953）爆發促使美國派遣第七艦隊協防臺灣海峽，將臺灣納入亞太防共島鏈防線；柏林圍牆於 1989 年倒塌，象徵冷戰鐵幕的瓦解與東西德統一的開端。','「冷戰」並非完全沒有戰爭，而是在美蘇兩大超級強權本土地區未爆發直接衝突，但各區域的代理人戰爭（韓戰、越戰、阿富汗戰爭）死傷極為慘重；冷戰期間也有不願結盟的「不結盟運動」第三世界國家。','在世界地圖上標示出冷戰時期的「第一道島鏈」位置（日本、南韓、臺灣、菲律賓），分析其在當時國際戰略佈局中的角色。',[
 ['第二次世界大戰結束後，美蘇兩大陣營展開長達四十餘年的「冷戰」，其主要特徵為？',['兩國每天進行大規模核武器對轟','意識形態與軍事政治對抗，透過代理人戰爭與軍備競賽競爭','全世界所有國家完全停止對外貿易','聯合國全面接管所有國家政府'],1,'冷戰是資本主義（美國）與共產主義（蘇聯）兩大陣營在未爆發全面直接軍事衝突下的全面地緣政治與軍備對抗。'],
 ['標誌著歐洲冷戰鐵幕分裂最著名的象徵，並於 1989 年被民眾推倒拆除的歷史建築是？',['萬里長城','柏林圍牆','馬奇諾防線','艾菲爾鐵塔'],1,'柏林圍牆將西柏林與東柏林阻絕，是冷戰東西陣營分裂最醒目的象徵；其倒塌預示了東歐共產體制的崩潰與冷戰結束。']]);
u('geography',7,2,'臺灣交通網絡與城鄉區域均衡發展','臺灣交通網絡包括環島鐵路網、高速鐵路、國道公路系統及海空運港口。高鐵串聯西部一日生活圈，促使西部各大都會區高度整合；雪山隧道與蘇花改縮短東部聯外時間。然而交通便捷也造成人口與經濟資源過度向「北北基桃」等都會核心集中，形成鄉村偏鄉人口外流、高齡化與產業空洞化，政府推動「地方創生」與區域均衡政策以減緩城鄉差距。','臺灣高鐵通車後，臺北至高雄縮短至 90 分鐘，商務客當日來回，促成西部走廊一日生活圈；但也加劇非高鐵沿線偏鄉小鎮的消費與人才向都會中心移轉。','興建快速交通雖然縮短通勤時間，但也可能引發「吸管效應（隧道效應）」，反將沿線小市鎮的資源快速吸納至大都市；改善偏鄉生活需要結合在地特色產業與公共服務網絡。','挑選一個臺灣推行「地方創生」的成功鄉鎮案例（如美濃客家文化、池上冠軍米藝術季），分析其如何將在地特色轉換為經濟動能。',[
 ['臺灣高鐵自 2007 年通車以來，對臺灣西部走廊空間與區域發展帶來的最顯著改變是？',['徹底取消所有台鐵一般列車','大幅縮短南北城際旅行時間，形成西部一日生活圈','使所有偏鄉小鎮人口瞬間暴增','導致所有跨縣市高速公路全部廢除'],1,'高鐵最高時速達 300 公里，將北高兩大都會區旅行時間縮減至 1.5 至 2 小時，深刻改變城際通勤、商務與觀光模式。'],
 ['面對臺灣鄉村地區因青年人口外移與少子高齡化帶來的市鎮萎縮問題，近年政府積極推動的區域活化政策是？',['全面禁止鄉村居民進入都市','地方創生政策，結合在地文化特色與產業永續經營','強制關閉所有鄉村學校與醫院','要求所有土地完全停止農業生產'],1,'「地方創生」鼓勵青年返鄉、運用在地自然與人文特色發展特色產業，減緩城鄉人口失衡與少子高齡化衝擊。']]);
u('geography',8,2,'西亞中亞乾燥氣候、伊斯蘭文化與石油地緣政治','西亞與中亞位居歐亞非三洲樞紐，受副熱帶高壓籠罩與深居內陸影響，以熱帶與溫帶沙漠、草原氣候為主，水資源極為珍貴（坎兒井、尼羅河與幼發拉底河底格里斯河灌溉）。此區為伊斯蘭教發源地（麥加為聖地），居民多數信奉伊斯蘭教（遵守古蘭經戒律，禁食豬肉與飲酒、每日朝拜、女性戴希賈布）。波斯灣沿岸蘊藏全球最豐富的石油與天然氣，主導 OPEC 石油組織，亦引發深刻的大國地緣政治衝突。','沙烏地阿拉伯、阿拉伯聯合大公國（杜拜）等國早期仰賴豐沛石油財富累積龐大主權基金，近年因應全球減碳積極投資海水淡化、太陽能與觀光金融多元轉型。','「中東/西亞居民全是阿拉伯人」是迷思；伊朗人主要是波斯人（講波斯語），土耳其人是突厥人後裔（講土耳其語），以色列人主要為猶太人（信仰猶太教）。','比較幼發拉底河、底格里斯河（美索不達米亞平原）與埃及尼羅河的灌溉農業，說明外流河在乾燥氣候區對文明孕育的關鍵作用。',[
 ['西亞與北非地區居民的生活方式與文化風俗，受到下列哪一個宗教的深刻規範與主導？',['基督教','伊斯蘭教','印度教','佛教'],1,'伊斯蘭教由先知穆罕默德於西亞阿拉伯半島創立，其教規深刻融入該地區居民的生活禮儀、飲食禁忌、法律與建築藝術中。'],
 ['波斯灣沿岸各國在國際政治與全球經濟中擁有極高話語權，最主要是因為該地區蘊藏極為豐富的？',['淡水水資源與熱帶木材','石油與天然氣能源資源','鑽石與金礦礦產','小麥與水稻穀物'],1,'波斯灣地區是全球石油與天然氣儲量最大、產量最高的地區，對全球能源供應與經濟運轉具有決定性影響。']]);
u('geography',9,1,'澳洲、紐西蘭與大洋洲島嶼地理環境','澳洲大陸地處南半球，為古老低平侵蝕陸塊，長期與其他大陸隔離，演化出袋鼠、無尾熊等特有有袋類生物；氣候呈半環狀分佈，東部大分水嶺攔截水氣，內陸多沙漠，東南部與西南部為溫帶地中海型與溫帶海洋性氣候，發展發達的小麥羊毛混合農業帶。紐西蘭由板塊碰撞擠壓形成，北島火山地熱、南島冰河峽灣地形險峻，發展高品質酪農業與奇異果。大洋洲島嶼分為美拉尼西亞、密克羅尼西亞與波里尼西亞三大群島，具珊瑚礁與火山島地景。','澳洲利用大自流盆地的自流水（含鹽分高不宜灌溉，但適合作為牲畜飲用水）發展大規模放牧業，羊毛與牛肉外銷全球，有「騎在羊背上的國家」之美譽。','澳洲大自流盆地的地下水含鹽度較高，多屬於「微鹹水」，不能直接用於農作物灌溉，主要用於牧牛牧羊之飲水；紐西蘭南島以冰河峽灣著稱，北島以火山地熱為主。','繪製簡圖標示澳洲東部大分水嶺與內陸大自流盆地，用盛行風向解釋為什麼澳洲內陸形成廣大沙漠與半乾燥草原。',[
 ['澳洲大陸之所以擁有眾多全世界獨一無二的原始特有生物（如袋鼠、無尾熊、鴨嘴獸），其最主要的地理原因是？',['全大陸終年處於冰雪嚴寒環境中','長期與其他大陸板塊地理隔離，生物獨立緩慢演化','人工基因改造技術引進','島嶼面積極小無法形成食物鏈'],1,'澳洲大陸很早就與其他大陸板塊分離漂移，阻絕了外來較高等真獸類哺乳動物的競爭，保留了豐富的有袋類古老生物群。'],
 ['紐西蘭的自然地理景觀極為多樣壯麗，其中南島西側最著名的地形景觀特徵為？',['熱帶雨林與紅樹林沼澤','冰河侵蝕形成的峽灣與雪山冰川','廣大無垠的熱帶流動沙丘','乾燥下陷的鹽鹼荒漠盆地'],1,'紐西蘭南島高聳的南阿爾卑斯山脈歷經強烈冰河切割侵蝕，形成壯觀的 U 型谷與沿海峽灣（如米佛峽灣）。']]);
u('civics',7,2,'地方自治、社區參與與地方創生','地方自治落實主權在民與因地制宜，由住民自主處理地方公共事務。地方政府採「行政、立法二元代表制」：行政機關（縣市政府、鄉鎮市區公所）執行地方政務與公共設施；立法機關（縣市議會、鄉鎮市民代表會）行使議決地方自治條例、審查地方預算與監督行政施政之權。公民可透過地方公民投票、里民大會與社區發展協會參與公共決策。','某縣市政府編列預算擬興建垃圾焚化廠，縣議會有權刪減或否決該筆預算；當地社區居民若有疑慮，亦可依法連署提出地方性公民投票，決定公共設施設置與否。','直轄市底下的「區公所」除原住民區外屬於市政府的派出行政機關，區長由市長指派，並無「區民代表會」；只有縣轄市、鄉、鎮才設有民選的鄉鎮市長與鄉鎮市民代表會。','調查你所在的縣市行政首長與在地選出的議員姓名，並列出一項近期該縣市議會討論的生活相關公共議題（如通學步道、公車路線）。',[
 ['我國地方自治組織中，負責「審查地方政府年度總預算」並「監督地方行政機關施政」的機關是？',['地方警察局','地方民意機關（如縣市議會）','行政院主計總處','地方地方法院'],1,'地方民意代表機關（縣市議會、鄉鎮市民代表會）代表人民行使立法監督權，負責議決自治條例與審查地方政府預算。'],
 ['依據地方制度法規定，下列地方行政區中，哪一個層級的首長是由市長直接派任（官派），而非由市民直接投票選舉產生？',['臺北市大安區公所區長','新竹市市長','彰化縣員林市市長','屏東縣恆春鎮鎮長'],0,'直轄市（如臺北市、新北市等）所轄之普通「行政區」，其區公所為市政府之派出機關，區長由直轄市長指派任用，無地方自治法人地位。']]);
u('civics',8,1,'中央政府體制與五院職權分工制衡','我國中央政府採「五權分立」架構：總統為國家元首（對外代表國家，統率三軍，公布法律，任命行政院長）；行政院為最高行政機關（向立法院負責提出施政方針與法律預算案）；立法院為最高立法機關（行使立法權、預算審查權、質詢權、不信任案與彈劾總統案）；司法院掌理審判、懲戒與憲法訴訟（憲法法庭判決法律違憲失效）；考試院掌理公務人員考試與任用；監察院行使彈劾、糾舉與審計權。','行政院若認為立法院通過的法律案或預算案窒礙難行，經總統核可後可移請立法院「覆議」；若立法院全體立法委員二分之一以上決議維持原案，行政院長即應接受該決議。','「彈劾總統」是由「立法院」提出提案後，聲請「司法院憲法法庭」審理判決，而非監察院職權；監察院負責彈劾違法失職的中央與地方公務人員（不含民選民意代表與總統副總統）。','畫出行政院與立法院之間的權力互動圖，標示「施政質詢」、「提出預算」、「覆議案」與「不信任案」四種相互制衡的機制。',[
 ['我國中央政府中，若行政機關訂定的行政命令或立法院通過的法律有牴觸憲法保障人權之疑慮時，負責審理並宣告其違憲失效的機關是？',['立法院程序委員會','司法院憲法法庭','行政院法規會','監察院國家人權委員會'],1,'司法院大法官組成「憲法法庭」，掌理憲法審查、審理法律或法規命令是否牴觸憲法，維護國家憲法最高性與基本人權。'],
 ['當立法院通過某項重大法案，行政院認為其執行有窒礙難行之處時，依法可透過何種憲政機制尋求救濟與制衡？',['立刻解散最高法院','經總統核可後，移請立法院提出「覆議」','由行政院長逕行更改憲法條文','強制扣押所有立法委員的薪水'],1,'憲法增修條文規定，行政院對立法院決議之法律案、預算案或條約案認為窒礙難行時，得經總統核可，移請立法院覆議。']]);
u('civics',9,1,'國際貿易、比較利益法則與全球分工','國際貿易使各國能跨越國界交換資源與產品。李嘉圖提出「比較利益法則」：在機會成本較低的項目上取得比較利益，各國應專業化生產並出口具有比較利益（機會成本較低）的商品，再透過自由貿易交換其他商品，使各國的總消費量超越各自的生產可能線，創造雙贏貿易利得。但貿易亦可能衝擊國內受進口競爭的弱勢產業，需要配套輔導。','臺灣在研發製造先進半導體晶片上具有高度比較利益，專精於晶圓代工並出口全球，同時從國外進口原油、天然氣與農產品，使兩造福祉極大化。','一個國家即使在所有產品的生產效率上都超越他國（具絕對利益），雙方依然能透過「比較利益（比誰的機會成本更低）」進行分工貿易，並從中共同獲益；貿易創造總體福利增加，但不代表國內每一個群體皆同等受惠。','甲國生產 1 噸小麥需放棄 2 輛汽車，乙國生產 1 噸小麥需放棄 4 輛汽車，計算誰在生產小麥上具有比較利益，並說明兩國如何互惠貿易。',[
 ['依據經濟學中的「比較利益法則」（Law of Comparative Advantage），各國在決定專業化分工生產與出口商品時，評估的核心標準是？',['該商品的外觀包裝是否最美觀','生產該商品時所放棄的其他商品價值（機會成本）是否最低','該國生產該商品的工人總數是否最多','生產該商品的工廠面積是否最大'],1,'比較利益以「機會成本」為衡量基準，機會成本相對較低者即具有比較利益，專業化生產該商品能提高整體生產效率與貿易利得。'],
 ['國際自由貿易雖然能提高各國整體消費福祉與資源配置效率，但對進口國而言，最常受衝擊的群體是？',['國內生產高品質出口商品的跨國企業','國內遭受廉價進口外國商品激烈競爭的本土弱勢生產者','所有享有更多低價多樣商品的廣大消費者','負責徵收關稅的海關稅捐機關'],1,'開放進口會使本土同類型產業面臨外國物美價廉商品的競爭壓力，造成產量縮減與從業人員失業衝擊，需要政府轉型輔導。']]);
}

